package com.gerenciadorrural.modules.herd.infrastructure;
import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.shared.tenancy.TenantId; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; import java.time.*; import java.util.*;
@Repository public class JdbcMovementOperationRepository implements MovementOperationRepository {private final NamedParameterJdbcTemplate jdbc; public JdbcMovementOperationRepository(NamedParameterJdbcTemplate jdbc){this.jdbc=jdbc;} public Optional<String> payload(TenantId t,UUID f,UUID o){return jdbc.query("select command_payload from app.herd_movement_operations where tenant_id=:tenantId and farm_id=:farmId and operation_id=:operationId",p(t,f,o),(r,n)->r.getString(1)).stream().findFirst();} public void save(TenantId t,UUID f,UUID o,String x){jdbc.update("insert into app.herd_movement_operations(tenant_id,farm_id,operation_id,command_payload) values(:tenantId,:farmId,:operationId,:payload)",p(t,f,o).addValue("payload",x));} public List<PaddockMovement> movements(TenantId t,UUID f,UUID id,int size,long offset){return jdbc.query("select e.id,a.id animal_id,a.identification,m.source_paddock_id,e.payload->>'sourcePaddockName' source_name,m.destination_paddock_id,e.payload->>'destinationPaddockName' destination_name,e.occurred_on,e.recorded_at,e.actor_user_id from app.herd_movements m join app.animal_events e on e.id=m.event_id join app.animals a on a.tenant_id=m.tenant_id and a.farm_id=m.farm_id and a.id=m.animal_id where m.tenant_id=:tenantId and m.farm_id=:farmId and (m.source_paddock_id=:id or m.destination_paddock_id=:id) order by e.recorded_at desc,e.id desc limit :size offset :offset",p(t,f,id).addValue("size",size).addValue("offset",offset),(r,n)->new PaddockMovement(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getObject(4,UUID.class),r.getString(5),r.getObject(6,UUID.class),r.getString(7),r.getObject(8,LocalDate.class),r.getObject(9,OffsetDateTime.class).toInstant(),r.getObject(10,UUID.class)));} public long countMovements(TenantId t,UUID f,UUID id){Long n=jdbc.queryForObject("select count(*) from app.herd_movements where tenant_id=:tenantId and farm_id=:farmId and (source_paddock_id=:id or destination_paddock_id=:id)",p(t,f,id),Long.class);return n==null?0:n;} private static MapSqlParameterSource p(TenantId t,UUID f,UUID o){return new MapSqlParameterSource().addValue("tenantId",t.value()).addValue("farmId",f).addValue("operationId",o).addValue("id",o);}}
